     1→package com.danawa.search.analysis.product;
     2→
     3→import java.io.IOException;
     4→import java.util.*;
     5→
     6→import com.danawa.search.analysis.dict.ProductNameDictionary;
     7→import com.danawa.search.analysis.dict.SetDictionary;
     8→import com.danawa.search.analysis.dict.SpaceDictionary;
     9→import com.danawa.search.analysis.dict.SynonymDictionary;
    10→import com.danawa.search.analysis.korean.KoreanWordExtractor;
    11→import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag;
    12→import com.danawa.search.analysis.product.rule.Entry;
    13→import com.danawa.search.analysis.product.rule.RuleEntry;
    14→import com.danawa.util.CharVector;
    15→
    16→import org.apache.logging.log4j.Logger;
    17→import org.apache.lucene.analysis.tokenattributes.ExtraTermAttribute;
    18→import org.apache.lucene.analysis.tokenattributes.CharTermAttribute;
    19→import org.apache.lucene.analysis.tokenattributes.OffsetAttribute;
    20→import org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute;
    21→import org.apache.lucene.analysis.tokenattributes.SynonymAttribute;
    22→import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute;
    23→import org.apache.lucene.analysis.tokenattributes.TypeAttribute;
    24→import org.apache.lucene.analysis.TokenFilter;
    25→import org.apache.lucene.analysis.TokenStream;
    26→import org.elasticsearch.common.logging.Loggers;
    27→
    28→import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
    29→
    30→public class ProductNameAnalysisFilter extends TokenFilter {
    31→
    32→	private static final Logger logger = Loggers.getLogger(ProductNameAnalysisFilter.class, "");
    33→	
    34→	private final CharTermAttribute termAttribute = addAttribute(CharTermAttribute.class);
    35→	private final TokenInfoAttribute tokenAttribute = addAttribute(TokenInfoAttribute.class);
    36→	private final OffsetAttribute offsetAttribute = addAttribute(OffsetAttribute.class);
    37→	private final ExtraTermAttribute extraTermAttribute = addAttribute(ExtraTermAttribute.class);
    38→	private final SynonymAttribute synonymAttribute = addAttribute(SynonymAttribute.class);
    39→	private final TypeAttribute typeAttribute = addAttribute(TypeAttribute.class);
    40→	private final PositionIncrementAttribute posIncrAtt = addAttribute(PositionIncrementAttribute.class);
    41→	private AnalyzerOption option;
    42→	
    43→	private KoreanWordExtractor extractor;
    44→	
    45→	private SynonymDictionary synonymDictionary;
    46→	private SpaceDictionary spaceDictionary;
    47→	private SetDictionary stopDictionary;
    48→	private ProductNameDictionary dictionary;
    49→	
    50→	private ProductNameParsingRule parsingRule;
    51→	private CharVector token;
    52→	private List<RuleEntry> termList;
    53→
    54→	// 이전 텀과 상대적인 거리. 1이면 한단어거리. 0이면 유사어등 같은 위치를 나타냄.
    55→	private int positionIncrement = 0;
    56→
    57→	public ProductNameAnalysisFilter(TokenStream input) {
    58→		super(input);
    59→	}
    60→
    61→	public ProductNameAnalysisFilter(TokenStream input, ProductNameDictionary dictionary, AnalyzerOption option) {
    62→		super(input);
    63→		if (dictionary != null) {
    64→			this.dictionary = dictionary;
    65→			this.synonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary.class);
    66→			this.spaceDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SPACE, SpaceDictionary.class);
    67→			this.stopDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_STOP, SetDictionary.class);
    68→		}
    69→		this.extractor = new KoreanWordExtractor(dictionary);
    70→		this.option = option;
    71→		extraTermAttribute.init(this);
    72→		termList = new ArrayList<>();
    73→		super.clearAttributes();
    74→		logger.trace("init");
    75→	}
    76→
    77→	public final boolean incrementToken() throws IOException {
    78→		boolean ret = false;
    79→		// FIXME : 큐 마지막에 ASCII 텀이 남아 있다면 모델명규칙 등을 위해 남겨 두어야 함.
    80→		// INFO : 텀 오프셋 불일치를 막기 위해 절대값을 사용 (버퍼 상대값은 되도록 사용하지 않음)
    81→		if (parsingRule == null) {
    82→			parsingRule = new ProductNameParsingRule(extractor, dictionary, option);
    83→		}
    84→		synonymAttribute.setSynonyms(null);
    85→		extraTermAttribute.init(this);
    86→
    87→		while (true) {
    88→			if (termList.size() == 0) {
    89→				if (tokenAttribute.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
    90→					ret = false;
    91→					break;
    92→				}
    93→				while (input.incrementToken()) {
    94→					// 한번 읽어온 버퍼를 다 소진할때까지 큐에 넣는다.
    95→					CharVector ref = tokenAttribute.ref();
    96→					String type = typeAttribute.type();
    97→					PosTag posTag = tokenAttribute.posTag();
    98→
    99→					// 색인시에는 전체텀을 추출하지 않는다.
   100→					if (!(option.useForQuery() && option.useFullString()) && FULL_STRING.equals(type)) {
   101→						continue;
   102→					}
   103→					Entry.addEntry(termList, ref, type, posTag,
   104→						offsetAttribute.startOffset(), offsetAttribute.endOffset(), spaceDictionary);
   105→					if (tokenAttribute.isState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)) {
   106→						break;
   107→					}
   108→				} // LOOP (incrementToken())
   109→				// RULE PROCESS
   110→				if (termList.size() > 0) {
   111→//					parsingRule.init(termList);
   112→					parsingRule.processRule(termList, true);
   113→				}
   114→				logger.trace("ENTRY QUEUE-SIZE:{}", termList.size());
   115→			} else {
   116→				// 엔트리를 출력할때 오프셋 순서대로 정렬하여 출력한다.
   117→				RuleEntry entry = null;
   118→				while ((entry = termList.get(0)) == null) {
   119→					termList.remove(0);
   120→				}
   121→
   122→				List<RuleEntry> subEntryList = entry.subEntry;
   123→				CharSequence[] synonyms = entry.synonym;
   124→				logger.trace("SUB:{} / {} / {}", entry, synonyms, subEntryList);
   125→
   126→				// 분기. ES에서는 Synonym, ExtraTerm 등의 Attribute를 쓸수 없으므로
   127→				// 색인시에는 동의어, 추가어를 일반텀으로 추출함.
   128→				// 질의시에는 Synonym, ExtraTerm 속성으로 추출 하되 
   129→				// 따로 ES 에 질의 가능한 질의문을 생성하여 처리한다.
   130→				// 색인시에는 오프셋이 앞으로 갈수 없으므로 긴 텀부터 순서대로 일반텀 추출한다
   131→
   132→				if (option.useForQuery()) {
   133→					// 질의용
   134→					if(subEntryList != null) {
   135→						//질의어에서는 단위명의 숫자만을 뽑지는 않는다. (검색의 정확도를 위해)
   136→						//역으로는 뽑아야 한다. (1,204 를 검색할 경우 1,024gb 를 포함해야 하지만 1,024gb 를 검색했을 때 1,024 가 검색되지는 않는다.
   137→						if(entry.type == UNIT || entry.type == UNIT_ALPHA) {
   138→							for (int sinx = 0; sinx < subEntryList.size(); sinx++) {
   139→								if (subEntryList.get(sinx).type == NUMBER || 
   140→									subEntryList.get(sinx).type == NUMBER_TRANS) {
   141→									subEntryList.remove(sinx);
   142→									sinx--;
   143→								}
   144→							}
   145→						}
   146→					}
   147→					testEntry(entry, null);
   148→					token = applyEntry(entry);
   149→					applySynonym(token, entry);
   150→					if (entry.subEntry != null && entry.subEntry.size() > 0) {
   151→						for (RuleEntry subEntry : entry.subEntry) {
   152→							List<CharSequence> synonymList = null;
   153→							CharVector cv = subEntry.makeTerm(null);
   154→							testEntry(subEntry, null);
   155→							if (option.useSynonym() && synonymDictionary.containsKey(cv)) {
   156→								synonymList = Arrays.asList(synonymDictionary.get(cv));
   157→								logger.trace("token:{} / synonym:{}", cv, synonymList);
   158→							}
   159→							extraTermAttribute.addExtraTerm(String.valueOf(cv), subEntry.type, synonymList);
   160→						}
   161→					}
   162→					termList.remove(0);
   163→					if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
   164→						logger.trace("STOP WORD:{}", token);
   165→						typeAttribute.setType(STOPWORD);
   166→						if (option.useStopword()) {
   167→							continue;
   168→						}
   169→					}
   170→					ret = true;
   171→					//positionIncrement증가.
   172→					positionIncrement = 1;
   173→					break;
   174→				} else {
   175→					// 색인용
   176→					if (entry.buf != null) {
   177→						logger.trace("TERMLIST:{}", termList);
   178→						logger.trace("SUB:{}", entry.subEntry);
   179→						logger.trace("SYN:{}{}", "", entry.synonym);
   180→						testEntry(entry, null);
   181→						token = applyEntry(entry);
   182→						subEntryList = entry.subEntry;
   183→						if (synonyms != null) {
   184→							// 동의어 -> 일반텀으로 변경
   185→							if (subEntryList == null) {
   186→								entry.subEntry = subEntryList = new ArrayList<>();
   187→							}
   188→							for (int sinx = 0; sinx < synonyms.length; sinx++) {
   189→								CharVector cv = new CharVector(synonyms[sinx]);
   190→								subEntryList.add(sinx, new RuleEntry(cv.array(), 0, cv.length(),
   191→									entry.startOffset, entry.endOffset, entry.type));
   192→							}
   193→							entry.synonym = synonyms = null;
   194→						}
   195→						if (subEntryList == null) {
   196→							termList.remove(0);
   197→						} else {
   198→							// 서브엔트리가 존재하는 경우 출력한 버퍼를 null 처리 하고 서브엔트리를 처리하도록 한다.
   199→							entry.buf = null;
   200→						}
   201→						if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
   202→							logger.trace("STOP WORD:{}", token);
   203→							typeAttribute.setType(STOPWORD);
   204→							if (option.useStopword()) {
   205→								continue;
   206→							}
   207→						}
   208→						ret = true;
   209→						//positionIncrement증가.
   210→						positionIncrement = 1;
   211→						break;
   212→					} else if (subEntryList.size() > 0) {
   213→						RuleEntry subEntry = subEntryList.get(0);
   214→						testEntry(subEntry, entry);
   215→						token = applyEntry(subEntry);
   216→						subEntryList.remove(0);
   217→						if (tokenAttribute.isState(TokenInfoAttribute.STATE_TERM_STOP)) {
   218→							logger.trace("STOP WORD:{}", token);
   219→							typeAttribute.setType(STOPWORD);
   220→							if (option.useStopword()) {
   221→								continue;
   222→							}
   223→						}
   224→						ret = true;
   225→						//positionIncrement 변화없음.
   226→						positionIncrement = 0;
   227→						break;
   228→					} else if (subEntryList.size() == 0) {
   229→						termList.remove(0);
   230→					}
   231→				}
   232→			}
   233→		} // LOOP
   234→
   235→		posIncrAtt.setPositionIncrement(positionIncrement);
   236→
   237→		if (logger.isTraceEnabled()) {
   238→			if (ret) {
   239→				logger.trace("TERM:{} / {}~{} / {} ", termAttribute, offsetAttribute.startOffset(), offsetAttribute.endOffset());
   240→			} else {
   241→				logger.trace("FILTER STOPPED!!");
   242→			}
   243→		}
   244→		return ret;
   245→	}
   246→
   247→	private void applySynonym(CharVector token, RuleEntry entry) {
   248→		List<CharSequence> synonyms = new ArrayList<>();
   249→		if (option.useSynonym() && option.useForQuery()) {
   250→			if (synonymDictionary != null && synonymDictionary.containsKey(token)) {
   251→				CharSequence[] wordSynonym = synonymDictionary.get(token);
   252→				logger.trace("SYNONYM-FOUND:{}{}", "", wordSynonym);
   253→				if (wordSynonym != null) {
   254→					synonyms.addAll(Arrays.asList(wordSynonym));
   255→				}
   256→				// 동의어는 한번 더 분석해 준다.
   257→				// 단 단위명은 더 분석하지 않는다.
   258→				if (typeAttribute.type() != UNIT) {
   259→					List<CharSequence> synonymsExt = synonymExtract(synonyms, entry);
   260→					if (synonymsExt != null) {
   261→						synonyms = synonymsExt;
   262→					}
   263→				}
   264→			}
   265→		}
   266→		// 본래 entry 에 있던 동의어는 이미 분석된 동의어 이므로 따로 처리할 필요가 없다.
   267→		if (entry.synonym != null && option.useSynonym()) {
   268→			synonyms.addAll(Arrays.asList(entry.synonym));
   269→		}
   270→		if (synonyms.size() > 0) {
   271→			logger.trace("SET-SYNONYM:{}", synonyms);
   272→			synonymAttribute.setSynonyms(synonyms);
   273→		}
   274→	}
   275→
   276→	public List<CharSequence> synonymExtract(List<CharSequence> synonyms, RuleEntry entry) {
   277→		ProductNameParsingRule parsingRule = this.parsingRule.clone();
   278→		parsingRule.option = new AnalyzerOption();
   279→		parsingRule.option.useSynonym(false);
   280→		parsingRule.option.useStopword(true);
   281→		List<RuleEntry> entryList = new ArrayList();
   282→
   283→		List<CharSequence> result = null;
   284→		Set<String> dupSet = new HashSet<>();
   285→		for (int synonymInx = 0; synonymInx < synonyms.size(); synonymInx++) {
   286→			CharVector synonym = CharVector.valueOf(synonyms.get(synonymInx));
   287→			logger.trace("synonym:{}", synonym);
   288→
   289→			List<CharVector> synonymTokens = new ArrayList<>(1);
   290→			if (synonym instanceof CharVector) {
   291→				CharVector synonymCV = synonym;
   292→				// 유사어가 공백이 포함된 여러어절로 구성되어 있을 경우 처리.
   293→				if (synonymCV.hasWhitespaces()) {
   294→					List<CharVector> terms = synonymCV.splitByWhitespace();
   295→					for (CharVector term : terms) {
   296→						if (term.length() > 0) {
   297→							synonymTokens.add(term);
   298→						}
   299→					}
   300→				} else {
   301→					synonymTokens.add(synonymCV);
   302→				}
   303→			}
   304→
   305→			// 어절별로 처리한다. 하나의 어절에서 여러 단어가 나올수 있다.
   306→			StringBuilder sb = new StringBuilder();
   307→			for (CharVector synonymCV : synonymTokens) {
   308→				logger.trace("TRACING SYNONYM : {}", synonymCV);
   309→				extractor.setInput(synonymCV.array(), synonymCV.offset(), synonymCV.length());
   310→				KoreanWordExtractor.ExtractedEntry cvEntry = extractor.extract();
   311→				// 분석된 동의어에서 분석된 단어들은 차후 AND 조건으로 이어져야 한다.
   312→				while (cvEntry != null) {
   313→					CharVector cv = synonymCV.clone();
   314→					cv.offset(cvEntry.offset());
   315→					cv.length(cvEntry.column());
   316→					if (cv.length() < synonymCV.length()) {
   317→						cv = cv.trim();
   318→						if (cv.length() > 0) {
   319→							// NOTE! 동의어를 모델명분석을 하는편과 하지 않는 편 어느쪽이 더 분석결과가 나은지 비교할 것.
   320→							Entry.addEntry(entryList, cv, getTermType(cv), cvEntry.posTag(),
   321→									entry.startOffset, entry.endOffset, spaceDictionary);
   322→						}
   323→					} else {
   324→						Entry.addEntry(entryList, synonymCV, getTermType(synonymCV), cvEntry.posTag(),
   325→								entry.startOffset, entry.endOffset, spaceDictionary);
   326→						break;
   327→					}
   328→					cvEntry = cvEntry.next();
   329→				}
   330→
   331→				if (entryList.size() > 0) {
   332→					logger.trace("SYNONYM-QUEUE:{}", entryList);
   333→					parsingRule.processRule(entryList, false);
   334→					CharVector token = new CharVector();
   335→					while (entryList.size() > 0) {
   336→						entryList.remove(0).makeTerm(token);
   337→						if (sb.length() > 0) {
   338→							sb.append(" ");
   339→						}
   340→						sb.append(token.toString());
   341→					}
   342→				}
   343→			}
   344→
   345→			if (sb.length() > 0) {
   346→				String idString = sb.toString();
   347→				if (!dupSet.contains(idString)) {
   348→					if (result == null) {
   349→						result = new ArrayList<>();
   350→					}
   351→					result.add(idString);
   352→					logger.trace("synonym:{}", idString);
   353→					dupSet.add(idString);
   354→				}
   355→			}
   356→		}
   357→		return result;
   358→	}
   359→
   360→	public void testEntry(RuleEntry entry, RuleEntry parent) {
   361→		if ((parent == null || parent.type == MODEL_NAME) && entry.type == NUMBER && entry.length >= 5) {
   362→			entry.type = MODEL_NAME;
   363→		} else if (entry.type == UNIT_ALPHA) {
   364→			entry.type = UNIT;
   365→		} else if (entry.type == NUMBER_TRANS) {
   366→			entry.type = NUMBER;
   367→			CharVector entryStr = new CharVector(entry.makeTerm(null).toString().replace(",", ""));
   368→			if (entryStr.length() != entry.length) {
   369→				if (option.useForQuery()) {
   370→					if (entry.length != entryStr.length()) {
   371→						extraTermAttribute.addExtraTerm(entryStr.toString(), NUMBER, null);
   372→					}
   373→				} else if (parent != null) {
   374→					List<RuleEntry> subEntryList = parent.subEntry;
   375→					// parent 가 존재한다면 subEntryList 가 null 일 이유는 없으므로 
   376→					// 현재(2021.02.09)는 불필요 코드
   377→					if (subEntryList == null) {
   378→						subEntryList = new ArrayList<>();
   379→						parent.subEntry = subEntryList;
   380→					}
   381→					// 여기까지 정상적으로 타고 들어왔다면 subEntryList[0] = entry 임
   382→					if (subEntryList.get(0) == entry) {
   383→						subEntryList.add(1, new RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
   384→							entry.startOffset, entry.endOffset, entry.type));
   385→					}
   386→				} else {
   387→					List<RuleEntry> subEntryList = entry.subEntry;
   388→					if (subEntryList == null) {
   389→						subEntryList = new ArrayList<>();
   390→						entry.subEntry = subEntryList;
   391→					}
   392→					subEntryList.add(new RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
   393→						entry.startOffset, entry.endOffset, entry.type));
   394→				}
   395→			}
   396→		} else if (entry.type == null) {
   397→			entry.type = UNCATEGORIZED;
   398→		}
   399→	}
   400→
   401→	private CharVector applyEntry(RuleEntry entry) {
   402→		CharVector ret;
   403→		termAttribute.copyBuffer(entry.buf, entry.start, entry.length);
   404→		offsetAttribute.setOffset(entry.startOffset, entry.endOffset);
   405→		typeAttribute.setType(entry.type);
   406→		if (option.toUppercase()) {
   407→			toUppercase(termAttribute.buffer());
   408→		}
   409→		token = entry.makeTerm(null);
   410→		if (stopDictionary != null && stopDictionary.set().contains(token)) {
   411→			tokenAttribute.addState(TokenInfoAttribute.STATE_TERM_STOP);
   412→		} else {
   413→			tokenAttribute.rmState(TokenInfoAttribute.STATE_TERM_STOP);
   414→		}
   415→		ret = entry.makeTerm(null);
   416→		return ret;
   417→	}
   418→
   419→	public void reset() throws IOException {
   420→		super.reset();
   421→		extraTermAttribute.init(this);
   422→		parsingRule = null;
   423→		token = null;
   424→		termList = new ArrayList<>();
   425→		this.clearAttributes();
   426→	}
   427→
   428→	public void toUppercase(char[] buffer) {
   429→		for (int inx = 0; inx < buffer.length; inx++) {
   430→			buffer[inx] = Character.toUpperCase(buffer[inx]);
   431→		}
   432→	}
   433→}

