   187→							// FULL-TERM. 색인시에는 추출하지 않음 (필터에서 걸러짐)
   188→							tokenAtt.ref(newBuffer, 0, tokenLength);
   189→							tokenAtt.posTag(null);
   190→							offsetAtt.setOffset(0, tokenLength);
   191→							typeAtt.setType(FULL_STRING);
   192→							return true;
   193→						}
   194→						position = 0;
   195→						bufferStart = 0;
   196→						chrCurrent = 0;
   197→						typeCurrent = null;
   198→					}
   199→					{
   200→						////////////////////////////////////////////////////////////////////////////////
   201→						// 2. 버퍼 내 단순 토크닝 (공백 / 특수기호에 의한 분해)
   202→						////////////////////////////////////////////////////////////////////////////////
   203→						char chrPrev = chrCurrent;
   204→						String typePrev = typeCurrent;
   205→						chrCurrent = buffer[position];
   206→						typeCurrent = getType(chrCurrent);
   207→						position ++;
   208→						int pass = 1;
   209→
   210→						if (typePrev == null) {
   211→							// 이전문자가 없다면 패스
   212→						} else if (typePrev == WHITESPACE && typeCurrent != WHITESPACE) {
   213→							// 
   214→						} else if (typePrev == WHITESPACE && typeCurrent == WHITESPACE) {
   215→							// 공백뒤 공백. 오프셋 위치 변경
   216→							pass = 2;
   217→						} else if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
   218→							// 일반문자 뒤 공백. 끊어줌.
   219→							pass = 0;
   220→						} else if (typePrev != typeCurrent) {
   221→							// 2021.06.23
   222→							// 토크닝 수준에서 일부 떨어지고 일부 붙어서 오분석이 나오기 때문에
   223→							// 모두 떨어뜨려서 한글분석을 거침
   224→							// 2021.04.26 swsong
   225→							// 숫자+단위명 조합은 parsingRule에서 다시한번 확인하므로 여기서는 떨어져있어도 무방.
