    70→		String josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도";
    71→		String[] jl = josaList.split("\\s");
    72→		for (String j : jl) {
