    90→
    91→	/*
    92→	 * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
    93→	 */
    94→	private ExtractedEntry doSegment() {
    95→		CharVector cv = new CharVector(source, offset, length);
    96→		// 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
    97→		if (length == 1) {
    98→			// FIXME 나중엔 뺀다. extractor를 제일 먼저받을 것이기 때문..
    99→			// 조사이면 전체 조사로.
   100→			List<TagProb> tag = koreanDict.find(cv);
   101→			if (tag != null) {
   102→				return new ExtractedEntry(length - 1, length, tag.get(0), offset);
   103→			}
   104→			if (isDigit(cv)) {
   105→				return new ExtractedEntry(length - 1, length, TagProb.DIGIT, offset);
   106→			} else if (isSymbol(cv)) {
   107→				return new ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset);
   108→			}
   109→			return new ExtractedEntry(length - 1, length, TagProb.UNK, offset);
   110→		}
   111→		List<TagProb> tag = koreanDict.find(cv);
   112→		if (tag != null) {
   113→			return new ExtractedEntry(length - 1, length, tag.get(0), offset);
   114→		}
   115→		int start = length - 1;
   116→		for (int row = start; row >= 0; row--) {
   117→			for (int column = row + 1; column >= 1; column--) {
   118→				cv.init(offset + row - column + 1, column);
   119→				List<TagProb> tagList = null;
   120→				boolean isAlpha = false;
   121→				if (isDigit(cv)) {
   122→					// 무조건 셋팅.
   123→					tabular[row][column] = new PosTagProbEntry(TagProb.DIGIT);
   124→					status[row]++;
   125→				} else if (isSymbol(cv)) {
   126→					tabular[row][column] = new PosTagProbEntry(TagProb.SYMBOL);
   127→					status[row]++;
   128→				} else {
   129→					if (isAlpha(cv)) {
   130→						if (column == 1) {
   131→							tabular[row][column] = new PosTagProbEntry(TagProb.ALPHA);
   132→							/* 2019.3.28 @swsong ALPHA 는 분석발견이 아니라고 가정한다. */
   133→							continue;
   134→						}
   135→						// 길이가 2이상이면 사전에서 확인해본다.
   136→						isAlpha = true;
   137→					}
   138→					tagList = koreanDict.find(cv);
   139→					if (tagList != null) {
   140→						if (column == length) {
   141→							// 완전일치시
   142→							// logger.debug("Exact match {}", cv);
   143→							return new ExtractedEntry(row, column, tagList.get(0), offset);
   144→						}
   145→						PosTagProbEntry chainedEntry = null;
   146→						for (int i = 0; i < tagList.size(); i++) {
   147→							TagProb tagProb = tagList.get(i);
   148→							if (i == 0) {
   149→								chainedEntry = new PosTagProbEntry(tagProb);
   150→								tabular[row][column] = chainedEntry;
   151→							} else {
   152→								chainedEntry = chainedEntry.next(tagProb);
   153→							}
   154→						}
   155→						status[row]++;
   156→					} else {
   157→
   158→						if (isAlpha) {
   159→							// 영문자이면 null이 아닌 ALPHA로 셋팅한다.
   160→							tabular[row][column] = new PosTagProbEntry(TagProb.ALPHA);
   161→						} else {
   162→							tabular[row][column] = null;
   163→						}
   164→					}
   165→
   166→					if (column < 3) {
   167→						// 1글자가 조사인지.
   168→						if (josaSet.contains(cv)) {
   169→							PosTagProbEntry entry = new PosTagProbEntry(TagProb.JOSA);
   170→							if (tabular[row][column] == null) {
   171→								tabular[row][column] = entry;
   172→							} else {
   173→								entry.next = tabular[row][column];
   174→								tabular[row][column] = entry;
   175→							}
   176→							status[row]++;
   177→						}
   178→					}
   179→				}
   180→			}
   181→		}
   182→		return null;
   183→	}
   184→
   185→	// 유니코드 블럭인지 판단 (일부가 유니코드이면 유니코드 블럭으로 인식)
   186→	private boolean isUnicode(char[] buffer, int offset, int length) {
   187→		for (int inx = 0; inx < length; inx++) {
   188→			char ch = buffer[offset + inx];
   189→			if (ch > 127) {
   190→				return true;
   191→			}
   192→		}
   193→		return false;
   194→	}
   195→
   196→	// 단어가 전부숫자인지.
   197→	private boolean isDigit(CharVector cv) {
   198→		for (int i = 0; i < cv.length(); i++) {
   199→			char ch = cv.charAt(i);
   200→			if (ch >= '0' && ch <= '9') {
   201→				// 숫자면 다음을 본다.
   202→			} else {
   203→				return false;
   204→			}
   205→		}
   206→		return true;
   207→	}
   208→	
   209→	private boolean isAlpha(CharVector cv) {
   210→		for (int i = 0; i < cv.length(); i++) {
   211→			char ch = cv.charAt(i);
   212→			if ((ch >= 'a' && ch <= 'z') || ch >= 'A' && ch <= 'Z') {
   213→				// 다음을 본다.
   214→			} else {
   215→				return false;
   216→			}
   217→		}
   218→		return true;
   219→	}
   220→
   221→	private boolean isSymbol(CharVector cv) {
   222→		for (int i = 0; i < cv.length(); i++) {
   223→			int chInt = cv.charAt(i);
   224→			if (!Character.isLetterOrDigit(chInt)) {
   225→				// 다음을 본다.
   226→			} else {
   227→				return false;
   228→			}
   229→		}
   230→		return true;
   231→	}
   232→	
   233→	private void makeResult() {
   234→		int headRow = -1;
   235→		for (int row = length - 1; row >= 0; row--) {
   236→			if (status[row] > 0) {
   237→				// 분석결과가 존재하는지.
   238→				headRow = row;
   239→				break;
   240→			}
   241→		}
   242→
   243→		try {
   244→			if (headRow == -1) {
   245→				// 통째 미등록어.
   246→				addResult(new ExtractedEntry(length - 1, length, TagProb.UNK, offset));
   247→				return;
   248→			}
   249→			// 최초 char부터의 단어매칭이 없다면.
   250→			// 예를들어 "대한민국"분석시 "대한"만 사전에 있어서 "민국"은 결과가 없을경우.
   251→			if (headRow < length - 1) {
   252→				// 뒷부분을 미등록어로 처리한다. "대한(N)+민국(UNK)" 이 된다.
   253→				ExtractedEntry tail = new ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset);
   254→				connectAllTo(headRow, tail);
   255→			} else {
   256→				connectAllTo(headRow, null);
   257→			}
   258→			ExtractedEntry tail = null;
   259→			// logger.trace("Q:{}", queue);
   260→			while ((tail = queue.poll()) != null) {
   261→				// logger.trace("T:{}", tail);
   262→				int connectRow = tail.row() - tail.column();
   263→				if (status[connectRow] > 0) {
   264→					connectAllTo(connectRow, tail);
   265→				} else {
   266→					//
