   278→	private int connectAllTo(int headRow, ExtractedEntry tail) throws AnalyzeExceedException {
   279→		PosTagProbEntry[] rowData = tabular[headRow];
   280→		int found = 0;
   281→		// 최장길이부터 찾는다.
   282→		for (int headColumn = headRow + 1; headColumn > 0; headColumn--) {
   283→			if (rowData[headColumn] != null) {
   284→				PosTagProbEntry tagEntry = rowData[headColumn];
   285→				entryStringer.set(tagEntry, source, headRow, headColumn, offset);
   286→				/* 2019.3.28 @swsong 알파벳은 무조건 성공분석으로 잡혀서 사전에 없는 단어들도 후보가 되어 ALPHA를 건너뛰게 한다. */
   287→				if (tagEntry.tagProb.posTag() != PosTag.ALPHA) {
   288→					connectTo(tagEntry, headRow, headColumn, tail);
   289→					found++;
   290→				}
   291→			}
   292→
   293→			// 갯수만큼 다 찾았으면 일찍 종료한다.
   294→			if (found >= status[headRow]) {
   295→				break;
   296→			}
   297→
   298→		}
   299→		// 추가 20190725 (영문인경우 모두 분석되어야 분석성공으로 만들도록)
   300→		// logger.trace("CHECK:{} / {}", isUnicode, result);
   301→		if (!isUnicode) {
   302→			for (int inx = 0; inx < result.size(); inx++) {
   303→				if (result.get(inx).last().posTag() == PosTag.UNK) {
   304→					result.remove(inx);
   305→					inx--;
   306→				}
   307→			}
   308→		}
   309→		return found;
   310→	}
