   312→	private int connectTo(PosTagProbEntry headTagEntry, int headRow, int headColumn, ExtractedEntry tail) throws AnalyzeExceedException {
   313→		// entryStringer.set(headTagEntry, source, headRow, headColumn, offset);
   314→		// logger.trace("CONNECTTO:{}/{}", entryStringer, tail);
   315→		// headColumn = -1 이면 앞쪽에 연결될 단어가 없는것이다.
   316→		if (tail == null) {
   317→			// 처음
   318→			int found = 0;
   319→			while (headTagEntry != null) {
   320→				ExtractedEntry headEntry = new ExtractedEntry(headRow, headColumn, headTagEntry.get(), offset);
   321→				if (headEntry.row() - headEntry.column() < 0) {
   322→					addResult(headEntry);
   323→				} else {
   324→					addQueue(headEntry);
   325→				}
   326→				headTagEntry = headTagEntry.next;
   327→				found++;
   328→			}
   329→			// 바로리턴.
   330→			return found;
   331→		}
   332→
   333→		if (headTagEntry == null) {
   334→			// 해당 row의 모든 column을 확인해본다.
   335→			for (int column = 1; column <= headRow + 1; column++) {
   336→				int row2 = headRow - column;
   337→				// head앞에 결합가능한 것이 있다면 현재 head를 미등록처 처리하고 링크로 이어준다.
   338→				// 앞쪽에 결합가능한것이 없으면 현재 head는 버린다.
   339→				// row2 < 0 는 어절의 처음에 도달한것임.
   340→				if (row2 < 0 || status[row2] > 0) {
   341→					// 2014-1-27처리..
   342→				}
   343→			}
   344→			return 1;
   345→		}
   346→		
   347→		int found = 0;
   348→		while (headTagEntry != null) {
   349→			if (isConnectableByRule(headTagEntry.get(), headRow, headColumn, tail)) {
   350→				ExtractedEntry newTail = modifyAndConnect(headTagEntry.get(), headRow, headColumn, tail);
   351→				if (newTail == null) {
   352→					// null이면 버리는것이므로 다음으로..
   353→				} else {
   354→					if (newTail.row() - newTail.column() < 0) {
   355→						addResult(newTail);
   356→					} else {
   357→						addQueue(newTail);
   358→					}
   359→					found++;
   360→				}
   361→			}
   362→			headTagEntry = headTagEntry.next;
   363→		}
   364→		return found;
   365→	}
