   415→			}
   416→		}
   417→		result.clear();
   418→		
   419→		String type = null;
   420→		String ptype = null;
   421→		String pptype = null;
   422→		if (length > tabular.length) {
   423→			logger.trace("LENGTH IS OVER THAN {} / {} / {}", length, tabular.length, offset);
   424→			// 내부적으로 자를 수 있는 기준을 살펴 본다.
   425→			// 자를수 있는 기준은 다음과 같다.
   426→			// 한글 사이의 특수 문자. ( & 제외 : 존슨&존스 등 )
   427→			for (int inx = offset + length; inx > offset; inx--) {
   428→				pptype = ptype;
   429→				ptype = type;
   430→				type = getType(buffer[inx - 1]);
   431→				if (logger.isTraceEnabled()) {
   432→					logger.trace("PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
   433→						inx - offset,
   434→						(pptype != null && (pptype != ALPHA && pptype != NUMBER)),
   435→						(inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&'),
   436→						(type != null), (pptype != null),
   437→						(inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&'),
   438→						(type != null && (type != ALPHA && type != NUMBER)));
   439→				}
   440→				if (((pptype != null && (pptype != ALPHA && pptype != NUMBER))
   441→						&& (inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&')
   442→						&& (type != null))
   443→						|| ((pptype != null) && (inx < buffer.length && ptype == SYMBOL && buffer[inx] != '&')
   444→							&& (type != null && (type != ALPHA && type != NUMBER)))) {
   445→					logger.trace("LENGTH:{} / {}", length - offset, tabular.length);
   446→					length = inx - offset;
   447→					if (length <= tabular.length) {
   448→						logger.trace("BREAK INTO {}", length);
   449→						break;
   450→					}
   451→				}
   452→			}
   453→			//여기까지 와서 찾지 못했다면, 앞에서부터 최초 타입이 달라지는 순간 끊어준다.
   454→			//영숫자+기호 : 한글
   455→			if (length > tabular.length) {
   456→				type = null;
   457→				for (int inx = offset; inx < (offset + length); inx++) {
   458→					ptype = type;
   459→					type = getType(buffer[inx]);
   460→					if (ptype != null && (
   461→						( (type == ALPHA || type == NUMBER || type == SYMBOL)
   462→							&& !(ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL) )
   463→						|| (!(type == ALPHA || type == NUMBER || type == SYMBOL)
   464→							&& (ptype == ALPHA || ptype == NUMBER || ptype == SYMBOL)) )) {
   465→						length = inx - offset;
   466→					}
   467→				}
   468→			}
   469→			
   470→			if (length > tabular.length) {
   471→				if (logger.isTraceEnabled()) {
   472→					logger.trace("CUT TABULAR SIZE : {}/ {} -> {}", length, new String(buffer, offset, length), new String(buffer, offset, tabular.length));
   473→				}
   474→				remnantOffset = tabular.length;
   475→				remnantLength = length - tabular.length;
   476→				length = tabular.length;
   477→			}
   478→		}
   479→		length = setInput0(buffer, offset, length);
   480→		return length;
   481→	}
