   570→	/*
   571→	 * 두 PosTag간의 룰기반 접속문법검사
   572→	 */
   573→	protected boolean isConnectableByRule(TagProb headTagProb, int headRow, int headColumn, ExtractedEntry tail) {
   574→		//숫자끼리는 과분석된것이므로 연결해주지 않는다. 제일 긴 숫자가 사용하도록함.
   575→		if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   576→			return false;
   577→		}
   578→		if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   579→			return false;
   580→		}
   581→		if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   582→			return false;
   583→		}
   584→		if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   585→			// //은,이 와 는,가 일때 앞의 단어에 받침이 있는 지 확인.
   586→			if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   587→				// "은 는 이 가 을 를 에 과 와 의 께";
   588→				char ch = source[offset + tail.row() - tail.column() + 1];
   589→				if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
   590→					if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   591→						return false;
   592→					}
   593→				} else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
   594→					if (MorphUtil.hasLastElement(source[offset + headRow])) {
   595→						return false;
   596→					}
   597→				}
   598→			}
   599→		}
   600→
   601→		// 두개 모두 한글자분석이면서 점수가 -12이하인것이 하나라도 있으면 통짜로 미등록어처리.
   602→		if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   603→			if (tabular[tail.row()][tail.column() + headColumn] != null) {
   604→				// 단어가 존재하므로 버린다.
   605→				return false;
   606→			}
   607→		}
   608→		//3개연속 불허용.
   609→		return true;
   610→	}
