   612→	/*
   613→	 * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
   614→	 */
   615→	protected ExtractedEntry modifyAndConnect(TagProb tagProb, int row, int column, ExtractedEntry tail) {
   616→		ExtractedEntry newEntry = new ExtractedEntry(row, column, tagProb, offset);
   617→		return newEntry.next(tail);
   618→	}
