   620→	private ExtractedEntry finalCheck(ExtractedEntry headEntry) {
   621→		// 첫글자 조사버림.
   622→		if (headEntry.posTag() == PosTag.J) {
   623→			return null;
   624→		}
   625→
   626→		int count = 0;
   627→		if (headEntry.entryCount() >= 2) {
   628→			ExtractedEntry current = headEntry;
   629→			while (current != null) {
   630→				if (current.column() > 1) {
   631→					break;
   632→				} else {
   633→					count++;
   634→				}
   635→				current = current.next();
   636→			}
   637→		}
   638→
   639→		if (count == headEntry.entryCount()) {
   640→			if (headEntry.last().posTag() == PosTag.J) {
   641→				return headEntry;
   642→			}
   643→			return null;
   644→		}
   645→		/*
   646→		 * 한글자 + GUESS(or -15미만) 결합은 합친다.
   647→		 */
   648→		return headEntry;
   649→	}
