   652→	 * Best 결과를 뽑을때 사용하는 비교로직.
   653→	 */
   654→	protected boolean isBetterThan(ExtractedEntry entry, ExtractedEntry bestEntry) {
   655→		// 적게 잘린쪽이 우선.
   656→		// 2014-1-27 처리.. 이렇게 하면 무조건 항상 통 UNK가 나오게 된다.
   657→
   658→		// 점수가 큰쪽이 우선.
   659→		if (entry.totalScore() > bestEntry.totalScore()) {
   660→			return true;
   661→		}
   662→		return false;
   663→	}
